const crypto = require('crypto');
const body = JSON.stringify({type: 'LeadFound', payload: {email: $json.body.email, company: $json.body.company, source: 'web-form'}});
const ts = Math.floor(Date.now()/1000).toString();
const nonce = crypto.randomBytes(16).toString('hex');
const path = '/v1/integrations/events';
const sts = ['POST', path, ts, nonce, crypto.createHash('sha256').update(body).digest('hex')].join('\n');
const sig = crypto.createHmac('sha256', $env.AICOS_N8N_SIGNING_KEY).update(sts).digest('hex');
return [{json: {body, headers: {'X-AICOS-Key-Id': 'n8n', 'X-AICOS-Timestamp': ts, 'X-AICOS-Nonce': nonce, 'X-AICOS-Signature': sig}}}];
